\begin{aligned}
\rho_{\mathcal{C}}(\bm{y}_2) &= \frac12 \|\bm{y}_2 - \bm{p}_2\|_2^2 \\&\leq \frac12 \|\bm{y}_2 - \bm{p}_1\|_2^2\qquad {\small(\text{因为 $\bm{p}_2$ 是 $\bm{y}_2$ 的投影, 而 $\bm{p}_1 \in \mathcal{C}$ 是任意可行点})}\\
&= \frac12 \|\bm{y}_1 - \bm{p}_1 + \bm{y}_2 - \bm{y}_1\|_2^2\\
&= \frac12 \|\bm{y}_1 - \bm{p}_1\|_2^2 + \frac12 \|\bm{y}_2 - \bm{y}_1\|_2^2 + \langle \bm{y}_1 - \bm{p}_1, \bm{y}_2 - \bm{y}_1 \rangle\\
&=  \rho_{\mathcal{C}}(\bm{y}_1) + \langle \bm{y}_1 - \bm{p}_1, \bm{d} \rangle + \frac12 \|\bm{d}\|_2^2.
\end{aligned}
